window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8733dd1037441834"]={"versions": [{"id": "FIG-8733dd1037441834", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des Metamodell-Ausschnitts für Schnittstellen (<code>PortInterface</code>) im Kontext der Interaktion zwischen AUTOSAR-Authoring-Werkzeugen und Verhaltensmodellierungswerkzeugen (<code>Behavior Modeling</code>). Das Diagramm spezifiziert die Import-Beziehungen von Software-Komponenten des Verhaltensmodells zu AUTOSAR-Schnittstellenelementen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>PortInterface::PortInterface</code>: Abstrakte Basisklasse, spezialisiert als <code>ARElement</code>.</li>\n<li><code>PortInterface::SenderReceiverInterface</code>: Spezialisierung von <code>PortInterface</code>, enthält per Komposition (<code>+Interface</code> 1 zu <code>+dataElements 1..*</code>) mindestens ein <code>PortInterface::DataElementPrototype</code>.</li>\n<li><code>PortInterface::DataElementPrototype</code>: Datenprototyp innerhalb der Sender-Receiver-Schnittstelle, spezialisiert als <code>DataPrototype</code>.</li>\n<li><code>PortInterface::ClientServerInterface</code>: Spezialisierung von <code>PortInterface</code>.</li>\n<li><code>BM Software-Component</code> (aus dem Paket <code>Behavior Modeling</code>): Komponente des Verhaltensmodells mit Abhängigkeitsbeziehungen (<code>«import»</code>):</li>\n<li>Direkter Import von <code>PortInterface::DataElementPrototype</code>.</li>\n<li>Direkter Import von <code>PortInterface::ClientServerInterface</code>.</li>\n<li>Randbedingungen (OCL-Notiz an <code>PortInterface::ClientServerInterface</code>):</li>\n<li>Attributbedingung <code>IsService</code>: <code>ClientServerInterfaces</code> gehören nur dann zur Teilmenge, wenn <code>isService == true</code> ist (<code>context ClientServerInterface inv: self.isService = TRUE</code>).</li>\n<li>Erläuternde Notiz:</li>\n<li>Die Berücksichtigung von <code>PortInterface</code> ist primär für Round-Trip-Szenarien relevant, wenn im Verhaltensmodell neue Daten-Element-Prototypen ergänzt werden und das Verhaltensmodellierungs-Tool (BMT) Aufgaben des Authoring-Tools übernimmt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Ablauf- oder Sequenzdarstellung. Die gerichteten Abhängigkeiten (<code>«import»</code>) modellieren statische Modellimport-Pfade bei der Überführung von Schnittstellendefinitionen in das Verhaltensmodell.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Metamodell-Vorgabe für den Werkzeugaustausch und Modellimport:</p>\n<ul class=\"fig-list\">\n<li>Beim Import von Sender-Receiver-Kommunikation in eine Verhaltensmodell-Komponente (<code>BM Software-Component</code>) wird direkt auf <code>DataElementPrototype</code> referenziert; die umschließende <code>SenderReceiverInterface</code>-Struktur muss mindestens ein Datenelement umfassen (<code>1..*</code>).</li>\n<li>Für Client-Server-Schnittstellen gilt die OCL-Invariante <code>self.isService = TRUE</code>, womit ausschließlich Service-orientierte Client-Server-Schnittstellen für den Import durch die Verhaltenskomponente qualifiziert sind.</li>\n</ul>"}, {"id": "FIG-f5e7af2865ce149a", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des Metamodell-Ausschnitts für Schnittstellen (<code>PortInterface</code>) im Kontext der Interaktion zwischen AUTOSAR-Authoring-Werkzeugen und Verhaltensmodellierungswerkzeugen (<code>Behavior Modeling</code>). Das Diagramm spezifiziert die Import-Beziehungen von Software-Komponenten des Verhaltensmodells zu AUTOSAR-Schnittstellenelementen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>PortInterface::PortInterface</code>: Abstrakte Basisklasse, spezialisiert als <code>ARElement</code>.</li>\n<li><code>PortInterface::SenderReceiverInterface</code>: Spezialisierung von <code>PortInterface</code>, enthält per Komposition (<code>+Interface</code> 1 zu <code>+dataElements 1..*</code>) mindestens ein <code>PortInterface::DataElementPrototype</code>.</li>\n<li><code>PortInterface::DataElementPrototype</code>: Datenprototyp innerhalb der Sender-Receiver-Schnittstelle, spezialisiert als <code>DataPrototype</code>.</li>\n<li><code>PortInterface::ClientServerInterface</code>: Spezialisierung von <code>PortInterface</code>.</li>\n<li><code>BM Software-Component</code> (aus dem Paket <code>Behavior Modeling</code>): Komponente des Verhaltensmodells mit Abhängigkeitsbeziehungen (<code>«import»</code>):</li>\n<li>Direkter Import von <code>PortInterface::DataElementPrototype</code>.</li>\n<li>Direkter Import von <code>PortInterface::ClientServerInterface</code>.</li>\n<li>Randbedingungen (OCL-Notiz an <code>PortInterface::ClientServerInterface</code>):</li>\n<li>Attributbedingung <code>IsService</code>: <code>ClientServerInterfaces</code> gehören nur dann zur Teilmenge, wenn <code>isService == true</code> ist (<code>context ClientServerInterface inv: self.isService = TRUE</code>).</li>\n<li>Erläuternde Notiz:</li>\n<li>Die Berücksichtigung von <code>PortInterface</code> ist primär für Round-Trip-Szenarien relevant, wenn im Verhaltensmodell neue Daten-Element-Prototypen ergänzt werden und das Verhaltensmodellierungs-Tool (BMT) Aufgaben des Authoring-Tools übernimmt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Ablauf- oder Sequenzdarstellung. Die gerichteten Abhängigkeiten (<code>«import»</code>) modellieren statische Modellimport-Pfade bei der Überführung von Schnittstellendefinitionen in das Verhaltensmodell.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Metamodell-Vorgabe für den Werkzeugaustausch und Modellimport:</p>\n<ul class=\"fig-list\">\n<li>Beim Import von Sender-Receiver-Kommunikation in eine Verhaltensmodell-Komponente (<code>BM Software-Component</code>) wird direkt auf <code>DataElementPrototype</code> referenziert; die umschließende <code>SenderReceiverInterface</code>-Struktur muss mindestens ein Datenelement umfassen (<code>1..*</code>).</li>\n<li>Für Client-Server-Schnittstellen gilt die OCL-Invariante <code>self.isService = TRUE</code>, womit ausschließlich Service-orientierte Client-Server-Schnittstellen für den Import durch die Verhaltenskomponente qualifiziert sind.</li>\n</ul>"}], "trans": [{"from": "FIG-8733dd1037441834", "to": "FIG-f5e7af2865ce149a", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
